import{_ as n,o as t,c as a,a3 as r}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/schueler/werkzeuge-fehlende-abschnittsdaten.png",f=JSON.parse('{"title":"Fehlende Lernabschnittsdaten ergänzen","description":"","frontmatter":{"title":"Fehlende Lernabschnittsdaten ergänzen","source_pageid":741,"source_revision":4790},"headers":[],"relativePath":"schild3/schueler/fehlende-abschnittsdaten-anlegen-verwaltung-werkzeuge.md","filePath":"schild3/schueler/fehlende-abschnittsdaten-anlegen-verwaltung-werkzeuge.md"}'),l={name:"schild3/schueler/fehlende-abschnittsdaten-anlegen-verwaltung-werkzeuge.md"};function i(d,e,h,c,g,u){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="fehlende-lernabschnittsdaten-erganzen" tabindex="-1">Fehlende Lernabschnittsdaten ergänzen <a class="header-anchor" href="#fehlende-lernabschnittsdaten-erganzen" aria-label="Permalink to &quot;Fehlende Lernabschnittsdaten ergänzen&quot;">​</a></h1><p>Prüfen Sie auf fehlende Lernabschnitte und lassen Sie diese ergänzen, damit die Abschnittsdaten der Schülerinnen und Schüler vollständig vorliegen.</p><p><a href="/bilder/schueler/werkzeuge-fehlende-abschnittsdaten.png"><img src="'+s+'" alt="Fehlende Abschnittsdaten suchen und ggf. anlegen." loading="lazy"></a></p><p><em>Fehlende Abschnittsdaten suchen und ggf. anlegen.</em></p><p>Sucht bei Lernenden nach in der Vergangenheit und für den aktuellen Abschnitt fehlende Abschnittsdaten und legt diese gegebenenfalls an, damit die Datenbank konsistent ist.</p><p>Nach einem Halbjahres- oder Schuljahreswechsel sollten für alle aktuellen Schülerinnen und Schüler die zugehörigen Lernabschnitte vorhanden sein.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Fehlende_Abschnittsdaten_anlegen_(Verwaltung_Werkzeuge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4790.</p>',8)])])}const p=n(l,[["render",i]]);export{f as __pageData,p as default};
